-- Canada Computers physical stores (labels from product availability; list aligned with storelocator/list)
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name, city = EXCLUDED.city, province_code = EXCLUDED.province_code,
  latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude;

DELETE FROM stores WHERE slug = 'cc-edmonton' AND retailer_id = '00000000-0000-4000-a000-000000000103';